#!/bin/sh
# Generated by FWShift: a Google Cloud network firewall policy, created with gcloud. Read the report first: what is
# not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE                              prints the commands; needs no access to Google Cloud
#   GCLOUD_OPTS='--project my-project' sh THIS_FILE     creates the policy and its rules
#
# The policy is associated with no network: nothing changes for any traffic until you associate it:
#   gcloud compute network-firewall-policies associations create --firewall-policy fwshift --network NETWORK --global-firewall-policy
# It decides every connection of that network. Set the network's enforcement order to BEFORE_CLASSIC_FIREWALL, or
# the VPC firewall rules of the network decide first. A policy of the same name stops the script before anything is
# created; a command gcloud refuses stops it where it is (delete the policy and run it again).
set -u
DRY_RUN="${DRY_RUN:-}"
GCLOUD_OPTS="${GCLOUD_OPTS:-}"
POLICY=fwshift
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
run() {
  if [ -n "$DRY_RUN" ]; then printf 'gcloud' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gcloud "$@" $GCLOUD_OPTS --quiet >/dev/null || fail "gcloud $1 $2 $3 $4"
}
if [ -z "$DRY_RUN" ] && gcloud compute network-firewall-policies describe "$POLICY" --global $GCLOUD_OPTS >/dev/null 2>&1; then
  fail "a network firewall policy named $POLICY exists already; nothing was created"
fi

run compute network-firewall-policies create "$POLICY" --global '--description=Generated by FWShift; review the conversion report before associating it'

run compute network-firewall-policies rules create 1000 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=tcp:23,udp:23 '--description=layer 7 rule 2'
run compute network-firewall-policies rules create 1010 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=tcp:23,udp:23 '--description=layer 7 rule 2'
run compute network-firewall-policies rules create 1020 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=tcp:23,udp:23 '--description=layer 7 rule 2'
run compute network-firewall-policies rules create 1030 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=tcp:23,udp:23 '--description=layer 7 rule 2'
run compute network-firewall-policies rules create 1040 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=198.51.100.0/24 --layer4-configs=all '--description=layer 7 rule 3'
run compute network-firewall-policies rules create 1050 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=198.51.100.0/24 --layer4-configs=all '--description=layer 7 rule 3'
run compute network-firewall-policies rules create 1060 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=10.10.30.0/24,172.16.40.0/24 --layer4-configs=all --enable-logging '--description=ot cell isolated'
run compute network-firewall-policies rules create 1070 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=10.10.30.0/24,172.16.40.0/24 --layer4-configs=all --enable-logging '--description=ot cell isolated'
run compute network-firewall-policies rules create 1080 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=10.10.30.0/24,172.16.40.0/24 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --enable-logging '--description=ot no internet'
run compute network-firewall-policies rules create 1090 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=10.10.30.0/24,172.16.40.0/24 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --enable-logging '--description=ot no internet'
run compute network-firewall-policies rules create 1100 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1110 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1120 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1130 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny

# Not written:
#   inside a VLAN: intrazone rule: a rule of Google Cloud names no zones; the source of the rule is in zone vlan10-office, vlan20-servers, vlan30-ot-cell, and a rule of Google Cloud names no zone: give the networks behind vlan10-office, vlan20-servers, vlan30-ot-cell with --zone-network
#   office to servers web: the source of the rule is in zone vlan10-office, vlan20-servers, vlan30-ot-cell, and a rule of Google Cloud names no zone: give the networks behind vlan10-office, vlan20-servers, vlan30-ot-cell with --zone-network
#   historian: the source of the rule is in zone vlan10-office, vlan20-servers, vlan30-ot-cell, and a rule of Google Cloud names no zone: give the networks behind vlan10-office, vlan20-servers, vlan30-ot-cell with --zone-network
#   eng ws to plc: the source of the rule is in zone vlan10-office, vlan20-servers, vlan30-ot-cell, and a rule of Google Cloud names no zone: give the networks behind vlan10-office, vlan20-servers, vlan30-ot-cell with --zone-network
#   block update site: host name object fqdn updates.example.com: the rules are written with addresses
#   dns to servers: the source of the rule is in zone vlan10-office, vlan20-servers, vlan30-ot-cell, and a rule of Google Cloud names no zone: give the networks behind vlan10-office, vlan20-servers, vlan30-ot-cell with --zone-network
#   ping servers: the source of the rule is in zone vlan10-office, vlan20-servers, vlan30-ot-cell, and a rule of Google Cloud names no zone: give the networks behind vlan10-office, vlan20-servers, vlan30-ot-cell with --zone-network
#   office ipv6 out: the source of the rule is in zone vlan10-office, vlan20-servers, vlan30-ot-cell, and a rule of Google Cloud names no zone: give the networks behind vlan10-office, vlan20-servers, vlan30-ot-cell with --zone-network
#   passive ftp: the source of the rule is in zone vlan10-office, vlan20-servers, vlan30-ot-cell, and a rule of Google Cloud names no zone: give the networks behind vlan10-office, vlan20-servers, vlan30-ot-cell with --zone-network
#   bad ports: not converted: destination port '1024-5000,5004' cannot be read (one range, or a list of single ports); the source of the rule is in zone vlan10-office, vlan20-servers, vlan30-ot-cell, and a rule of Google Cloud names no zone: give the networks behind vlan10-office, vlan20-servers, vlan30-ot-cell wi
#   Default rule: the source of the rule is in zone vlan10-office, vlan20-servers, vlan30-ot-cell, and a rule of Google Cloud names no zone: give the networks behind vlan10-office, vlan20-servers, vlan30-ot-cell with --zone-network
#   vpn-portal: the source of the rule is in zone internet, and a rule of Google Cloud names no zone: give the networks behind internet with --zone-network; the destination of the rule is in zone vlan20-servers, and a rule of Google Cloud names no zone: give the networks behind vlan20-servers with --zone-network
#   mail (1): the source of the rule is in zone internet, and a rule of Google Cloud names no zone: give the networks behind internet with --zone-network; the destination of the rule is in zone vlan20-servers, and a rule of Google Cloud names no zone: give the networks behind vlan20-servers with --zone-network
#   mail (2): the source of the rule is in zone internet, and a rule of Google Cloud names no zone: give the networks behind internet with --zone-network; the destination of the rule is in zone vlan20-servers, and a rule of Google Cloud names no zone: give the networks behind vlan20-servers with --zone-network
#   scada-view: the source of the rule is in zone internet, and a rule of Google Cloud names no zone: give the networks behind internet with --zone-network; the destination of the rule is in zone vlan20-servers, and a rule of Google Cloud names no zone: give the networks behind vlan20-servers with --zone-network

echo 'Done. Associate the policy with the network when you are ready; until then nothing changes.' >&2
